"""Parsing helpers for invoice line items."""
from __future__ import annotations

import re
from decimal import Decimal, InvalidOperation

_CURRENCY_SYMBOLS = "$€£¥"
_AMOUNT_RE = re.compile(r"^-?\d+(\.\d{1,2})?$")


class ParseError(ValueError):
    """Raised when a field cannot be parsed."""


def strip_currency(raw: str) -> str:
    """Remove a leading currency symbol and surrounding whitespace."""
    text = raw.strip()
    if text and text[0] in _CURRENCY_SYMBOLS:
        text = text[1:]
    return text.strip()


def parse_amount(raw: str) -> Decimal:
    """Parse a money amount such as "$12.50" into a Decimal.

    Negative amounts may be written with a leading minus sign or in
    parentheses, as accountants do: "(12.50)" means -12.50.
    """
    text = strip_currency(raw)
    negative = text.startswith("(") and text.endswith(")")
    if negative:
        text = text[1:-1]
    if not _AMOUNT_RE.match(text):
        raise ParseError(f"not an amount: {raw!r}")
    try:
        value = Decimal(text)
    except InvalidOperation as exc:
        raise ParseError(f"not an amount: {raw!r}") from exc
    return -value if negative else value


def parse_quantity(raw: str) -> int:
    """Parse a whole-number quantity."""
    text = raw.strip()
    if not text.isdigit():
        raise ParseError(f"not a quantity: {raw!r}")
    return int(text)

from decimal import Decimal

import pytest

from invoice_tools.parse import ParseError, parse_amount, parse_quantity


def test_parse_amount_plain():
    assert parse_amount("12.50") == Decimal("12.50")


def test_parse_amount_currency():
    assert parse_amount("$12.50") == Decimal("12.50")


def test_parse_amount_parentheses_negative():
    assert parse_amount("(12.50)") == Decimal("-12.50")


def test_parse_amount_thousands():
    assert parse_amount("$1,234.50") == Decimal("1234.50")
